{
  "title": "Suspicious Permissive ACL Addition on Firewall",
  "id": "RULE-2026-1103-ACL",
  "description": "Detects addition of inbound allow rule for high‑risk ports (e.g., 4444) on perimeter firewalls.",
  "status": "experimental",
  "logsource": {
    "product": "firewall",
    "service": "configuration"
  },
  "detection": {
    "selection": {
      "eventid": "ACL_CHANGE",
      "action": "add",
      "direction": "inbound",
      "destination.port": "4444",
      "source.ip": "*"
    },
    "condition": "selection"
  },
  "level": "high",
  "tags": ["firewall", "acl", "unauthorized", "port_4444"]
}
